#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* Simple URL decoder: converts '+' to space and %XX hex to the corresponding byte */
static void url_decode(const char *src, char *dst) {
    while (*src) {
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else if (*src == '%' && isxdigit((unsigned char)src[1]) && isxdigit((unsigned char)src[2])) {
            char hex[3] = { src[1], src[2], '\0' };
            *dst++ = (char)strtol(hex, NULL, 16);
            src += 3;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
}

int main(void) {
    char line[2048];
    if (!fgets(line, sizeof(line), stdin)) {
        puts("NO_INPUT");
        return 0;
    }
    /* Strip trailing newline and carriage return */
    size_t len = strlen(line);
    while (len && (line[len-1] == '\n' || line[len-1] == '\r')) {
        line[--len] = '\0';
    }

    char *pair = line;
    while (pair && *pair) {
        char *amp = strchr(pair, '&');
        if (amp) *amp = '\0';

        char *eq = strchr(pair, '=');
        char key_buf[1024];
        char val_buf[1024];
        if (eq) {
            *eq = '\0';
            url_decode(pair, key_buf);
            url_decode(eq + 1, val_buf);
        } else {
            url_decode(pair, key_buf);
            val_buf[0] = '\0';
        }
        printf("%s=%s\n", key_buf, val_buf);

        if (amp) pair = amp + 1; else break;
    }
    return 0;
}
